package org.eclipse.rdf4j.rio.ntriples;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.BufferedWriter;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

/**
 * Compatibility of the stream constructor's exposed Writer with the JDK UTF-8 encoder. These checks deliberately use
 * getWriter(), including arbitrary UTF-16 input, so an encoding optimization cannot rely only on well-formed RDF
 * values.
 */
class NTriplesWriterEncodingTest {

	@Test
	void everyUnicodeScalarMatchesTheJdkThroughEveryWriteOverload() throws IOException {
		for (int start = 0; start <= Character.MAX_CODE_POINT; start += 4096) {
			StringBuilder input = new StringBuilder(8192);
			int end = Math.min(start + 4096, Character.MAX_CODE_POINT + 1);
			for (int codePoint = start; codePoint < end; codePoint++) {
				if (codePoint < Character.MIN_SURROGATE || codePoint > Character.MAX_SURROGATE) {
					input.appendCodePoint(codePoint);
				}
			}
			String text = input.toString();
			for (WriteMethod method : WriteMethod.values()) {
				assertEncoding(writer -> method.write(writer, text), method + " from U+" + Integer.toHexString(start));
			}
		}
	}

	@Test
	void everyIsolatedSurrogateMatchesTheJdkReplacement() throws IOException {
		StringBuilder input = new StringBuilder(6144);
		for (int surrogate = Character.MIN_SURROGATE; surrogate <= Character.MAX_SURROGATE; surrogate++) {
			input.append('L').append((char) surrogate).append('R');
		}
		String text = input.toString();
		for (WriteMethod method : WriteMethod.values()) {
			assertEncoding(writer -> method.write(writer, text), "isolated surrogates through " + method);
		}
	}

	@Test
	void malformedSequencesMatchTheJdkAcrossEveryWriteAndFlushSplit() throws IOException {
		String[] inputs = { "", "x", "\ud800", "\udc00", "\ud800x", "\udc00x", "x\ud800", "x\udc00",
				"\ud800\ud800", "\udc00\udc00", "\ud800\udc00", "\udbff\udfff", "\udc00\ud800",
				"\ud800\ud800\udc00", "\ud800\udc00\udc00", "\udc00\ud800\udc00",
				"\ud800\ud800\ud800", "\ud800\u0000\udc00", "a\ud800b\udc00c", "é\udbff\udfff€\ud800" };
		for (int input = 0; input < inputs.length; input++) {
			String text = inputs[input];
			for (int split = 0; split <= text.length(); split++) {
				String first = text.substring(0, split);
				String second = text.substring(split);
				for (WriteMethod method : WriteMethod.values()) {
					assertEncoding(writer -> {
						method.write(writer, first);
						writer.flush();
						writer.write("", 0, 0);
						writer.write(new char[0], 0, 0);
						method.write(writer, second);
						writer.flush();
					}, "malformed input " + input + ", split " + split + ", " + method);
				}
			}
		}
	}

	@Test
	void bulkWritesHandleMultibyteCharactersAtBufferBoundaries() throws IOException {
		int[] lengths = { 1022, 1023, 1024, 1025, 4094, 4095, 4096, 4097, 8190, 8191, 8192, 8193, 16383 };
		for (int length : lengths) {
			String text = "a".repeat(length) + "é€😀" + "b".repeat(length) + "\ud800x\udc00y\udbff\udfff";
			for (WriteMethod method : WriteMethod.values()) {
				assertEncoding(writer -> {
					writer.write("prefix");
					method.write(writer, text);
					writer.write("suffix");
				}, "buffer boundary " + length + ", " + method);
			}
		}
	}

	@Test
	void flushAndEmptyWritesRetainAPendingHighSurrogate() throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		Writer writer = new NTriplesWriter(output).getWriter();
		writer.write("before\ud83d");
		writer.flush();
		assertArrayEquals("before".getBytes(StandardCharsets.UTF_8), output.toByteArray());
		writer.write("ignored", 3, 0);
		writer.write(new char[] { 'x', 'y' }, 1, 0);
		writer.append("ignored", 2, 2);
		writer.flush();
		assertArrayEquals("before".getBytes(StandardCharsets.UTF_8), output.toByteArray());
		writer.write(new char[] { 'x', '\ude00', 'y' }, 1, 1);
		writer.flush();
		assertArrayEquals("before😀".getBytes(StandardCharsets.UTF_8), output.toByteArray());
		writer.write('\ud800');
		writer.flush();
		assertArrayEquals("before😀".getBytes(StandardCharsets.UTF_8), output.toByteArray());
		writer.close();
		assertArrayEquals("before😀?".getBytes(StandardCharsets.UTF_8), output.toByteArray());
	}

	@Test
	void mixedWriteOverloadsAndAppendRetainTheirWriterContracts() throws IOException {
		assertEncoding(writer -> {
			writer.append((CharSequence) null);
			writer.append(null, 1, 3);
			writer.append(new StringBuilder("prefixé😀suffix"), 6, 9);
			writer.write("prefix\ud83dsuffix", 6, 1);
			writer.write(new char[] { 'x', '\ude00', 'y' }, 1, 1);
			writer.write(0x1234d83d);
			writer.append('\ude00');
			writer.write(-1);
			writer.write(0x10000);
			writer.write(0x1f600);
			writer.write(0x110000);
		}, "mixed APIs and low sixteen bits of write(int)");
	}

	@Test
	void emptyNegativeAndOverflowedStringRangesRetainBufferedWriterNoOpBehavior() throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		Writer writer = new NTriplesWriter(output).getWriter();
		writer.write("before");
		// BufferedWriter intentionally does not validate String slices whose calculated end is at/before the start.
		writer.write("abc", 1, -1);
		writer.write("abc", -3, -1);
		writer.write("abc", Integer.MAX_VALUE, 2);
		writer.write("abc", Integer.MAX_VALUE, Integer.MAX_VALUE);
		writer.write("abc", 1, Integer.MIN_VALUE);
		writer.write("abc", Integer.MAX_VALUE, 0);
		writer.write((String) null, 7, 0);
		writer.write("after");
		writer.close();
		assertArrayEquals("beforeafter".getBytes(StandardCharsets.UTF_8), output.toByteArray());
	}

	@Test
	void closeIsIdempotentAndRejectsFurtherWritesAndFlushes() throws IOException {
		RecordingOutputStream output = new RecordingOutputStream();
		Writer writer = new NTriplesWriter(output).getWriter();
		writer.write("text\ud800");
		writer.close();
		writer.close();
		assertArrayEquals("text?".getBytes(StandardCharsets.UTF_8), output.toByteArray());
		assertEquals(1, output.closes);
		assertThrows(IOException.class, () -> writer.write('x'));
		assertThrows(IOException.class, () -> writer.write("text", 0, 4));
		assertThrows(IOException.class, () -> writer.write(new char[] { 'x' }, 0, 1));
		assertThrows(IOException.class, () -> writer.write("", 0, 0));
		assertThrows(IOException.class, () -> writer.write(new char[0], 0, 0));
		assertThrows(IOException.class, writer::flush);
	}

	@Test
	void writeAndFlushFailuresRetainTheirOriginalExceptions() throws IOException {
		IOException writeFailure = new IOException("byte write failed");
		Writer writer = new NTriplesWriter(new OutputStream() {
			@Override
			public void write(int value) throws IOException {
				throw writeFailure;
			}

			@Override
			public void write(byte[] value, int offset, int length) throws IOException {
				throw writeFailure;
			}
		}).getWriter();
		IOException thrown = assertThrows(IOException.class, () -> {
			writer.write("text".repeat(8192));
			writer.flush();
		});
		assertSame(writeFailure, thrown);

		IOException flushFailure = new IOException("stream flush failed");
		Writer flushingWriter = new NTriplesWriter(new ByteArrayOutputStream() {
			@Override
			public void flush() throws IOException {
				throw flushFailure;
			}
		}).getWriter();
		flushingWriter.write("text");
		assertSame(flushFailure, assertThrows(IOException.class, flushingWriter::flush));
	}

	@Test
	void closePreservesWriteFailureAndSuppressesCloseFailure() throws IOException {
		IOException writeFailure = new IOException("byte write failed");
		IOException closeFailure = new IOException("stream close failed");
		int[] closes = { 0 };
		Writer writer = new NTriplesWriter(new OutputStream() {
			@Override
			public void write(int value) throws IOException {
				throw writeFailure;
			}

			@Override
			public void write(byte[] value, int offset, int length) throws IOException {
				throw writeFailure;
			}

			@Override
			public void close() throws IOException {
				closes[0]++;
				throw closeFailure;
			}
		}).getWriter();
		writer.write("buffered");
		IOException thrown = assertThrows(IOException.class, writer::close);
		assertSame(writeFailure, thrown);
		assertArrayEquals(new Throwable[] { closeFailure }, thrown.getSuppressed());
		assertEquals(1, closes[0]);
		writer.close();
		assertEquals(1, closes[0]);
		assertThrows(IOException.class, () -> writer.write('x'));
	}

	private static void assertEncoding(WriterAction action, String context) throws IOException {
		ByteArrayOutputStream referenceOutput = new ByteArrayOutputStream();
		try (Writer reference = new BufferedWriter(new OutputStreamWriter(referenceOutput, StandardCharsets.UTF_8),
				1024)) {
			action.write(reference);
		}
		ByteArrayOutputStream actualOutput = new ByteArrayOutputStream();
		try (Writer actual = new NTriplesWriter(actualOutput).getWriter()) {
			action.write(actual);
		}
		assertArrayEquals(referenceOutput.toByteArray(), actualOutput.toByteArray(), context);
	}

	@FunctionalInterface
	private interface WriterAction {
		void write(Writer writer) throws IOException;
	}

	private enum WriteMethod {
		STRING,
		CHARACTER_ARRAY,
		CHARACTER;

		void write(Writer writer, String value) throws IOException {
			switch (this) {
			case STRING:
				writer.write("prefix" + value + "suffix", 6, value.length());
				break;
			case CHARACTER_ARRAY:
				writer.write(("prefix" + value + "suffix").toCharArray(), 6, value.length());
				break;
			case CHARACTER:
				for (int i = 0; i < value.length(); i++) {
					writer.write(value.charAt(i));
				}
				break;
			}
		}
	}

	private static final class RecordingOutputStream extends ByteArrayOutputStream {
		private int closes;

		@Override
		public void close() {
			closes++;
		}
	}
}
